/// `callback BlobCallback = undefined (Blob? blob);` (html.idl).
#[derive(Clone)]
pub struct BlobCallback(pub JsObject);

impl BlobCallback {
    /// Invokes the callback (Web IDL §3.12 "invoke a callback function"). A pending JS exception is
    /// `Err(Error::Pending)`.
    pub fn invoke(
        &self,
        cx: &mut Cx,
        this_arg: Option<&dyn ToJs>,
        blob: Option<Handle>,
    ) -> Result<()> {
        rt::in_callback_realm(cx, &self.0, None, |cx| {
            let scope: &v8::PinScope = cx.scope;
            let callee: v8::Local<v8::Value> = v8::Local::new(scope, &self.0 .0).into();
            let recv = rt::callback_this(scope, this_arg);
            let Ok(f) = v8::Local::<v8::Function>::try_from(callee) else {
                let r: v8::Local<v8::Value> = v8::undefined(scope).into();
                return {
                    let _ = r;
                    Ok(())
                };
            };
            let argv: [v8::Local<v8::Value>; 1] = [blob.to_js(scope).ok_or(rt::Error::Pending)?];
            let r = f.call(scope, recv, &argv).ok_or(rt::Error::Pending)?;
            {
                let _ = r;
                Ok(())
            }
        })
    }
}

impl ToJs for BlobCallback {
    fn to_js<'s>(&self, scope: &v8::PinScope<'s, '_>) -> Option<v8::Local<'s, v8::Value>> {
        self.0.to_js(scope)
    }
}

/// `callback CreateHTMLCallback = DOMString? (DOMString input, any arguments);` (trusted-types.idl).
#[derive(Clone)]
pub struct CreateHTMLCallback(pub JsObject);

impl CreateHTMLCallback {
    /// Invokes the callback (Web IDL §3.12 "invoke a callback function"). A pending JS exception is
    /// `Err(Error::Pending)`.
    pub fn invoke(
        &self,
        cx: &mut Cx,
        this_arg: Option<&dyn ToJs>,
        input: &str,
        arguments: Vec<JsValue>,
    ) -> Result<Option<String>> {
        rt::in_callback_realm(cx, &self.0, None, |cx| {
            let scope: &v8::PinScope = cx.scope;
            let callee: v8::Local<v8::Value> = v8::Local::new(scope, &self.0 .0).into();
            let recv = rt::callback_this(scope, this_arg);
            let Ok(f) = v8::Local::<v8::Function>::try_from(callee) else {
                let r: v8::Local<v8::Value> = v8::undefined(scope).into();
                return ({
                    let v = r;
                    if v.is_null_or_undefined() {
                        Some(None)
                    } else {
                        (rt::to_dom_string(scope, v)).map(Some)
                    }
                })
                .ok_or(rt::Error::Pending);
            };
            let mut argv: Vec<v8::Local<v8::Value>> =
                vec![input.to_js(scope).ok_or(rt::Error::Pending)?];
            for x in &arguments {
                argv.push(x.to_js(scope).ok_or(rt::Error::Pending)?);
            }
            let r = f.call(scope, recv, &argv).ok_or(rt::Error::Pending)?;
            ({
                let v = r;
                if v.is_null_or_undefined() {
                    Some(None)
                } else {
                    (rt::to_dom_string(scope, v)).map(Some)
                }
            })
            .ok_or(rt::Error::Pending)
        })
    }
}

impl ToJs for CreateHTMLCallback {
    fn to_js<'s>(&self, scope: &v8::PinScope<'s, '_>) -> Option<v8::Local<'s, v8::Value>> {
        self.0.to_js(scope)
    }
}

